import unittest
from solution import word_tally

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(word_tally("a b a"), {"a": 2, "b": 1})
    def test_case(self):
        self.assertEqual(word_tally("Hi hi HI"), {"hi": 3})
    def test_empty(self):
        self.assertEqual(word_tally(""), {})
    def test_whitespace(self):
        self.assertEqual(word_tally("a  b\ta\nb"), {"a": 2, "b": 2})
    def test_single(self):
        self.assertEqual(word_tally("solo"), {"solo": 1})
